@startuml
class RepairShop {
  +name : string
  +address : string
  +numberOfEmployees : int
}

class Employee {
  +taxCode : string
  +address : string
  +phoneNumber : string
  +yearsOfService : int
}

class Director {
  +taxCode : string
  +address : string
  +phoneNumber : string
  +age : int
}

class Repair {
  +code : string
  +checkInTime : datetime
  +checkInDate : date
  +returnTime : datetime
  +returnDate : date
}

class Vehicle {
  +model : string
  +type : string
  +licensePlate : string
  +yearOfRegistration : int
}

class Owner {
  +taxCode : string
  +address : string
  +phoneNumber : string
}

class Manager {
}

class AccountingOffice {
}

RepairShop "1" *-- "1" Director : manages
RepairShop "1" *-- "*" Employee : employs
RepairShop "1" -- "*" Repair : performs
RepairShop "1" -- "1" Manager : managed by
RepairShop "1" -- "1" AccountingOffice : communicates results to
Employee "1" -- "1" Director : is a
Vehicle "1" -- "1" Owner : owned by
Vehicle "1" -- "*" Repair : undergoes
Owner "1" -- "*" Vehicle : owns
@enduml

